// Desktop generator: the Web app (generated by the Web generator) wrapped in a Tauri 1.x project.
import './blocks.js';
import { defineGenerator } from '../../sdk/index.js';
import { J } from '../../i18n-helpers.js';
import { targetConfig } from '../../model.js';
import { generate as generateWeb } from '../../generator.js';
import { encodePng } from '../../png.js';

const IDENT = /^[a-z][a-z0-9-]*(\.[a-z][a-z0-9-]*)+$/;
const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

export const defaultDesktopConfig = (id = 'my-app', name = 'My App') => ({
  type: 'desktop', appName: name, identifier: 'com.example.' + (slug(id).replace(/-/g, '') || 'myapp'), version: '1.0.0', width: 1000, height: 700,
});
export const validateDesktopConfig = (cfg) => {
  const out = [];
  if (!(cfg.appName || '').trim()) out.push('アプリ名が空です');
  if (!IDENT.test(cfg.identifier || '')) out.push('識別子は com.example.myapp のように小文字・数字・- を . で区切って指定してください');
  if (!/^\d+\.\d+\.\d+/.test(cfg.version || '')) out.push('バージョンは 1.0.0 の形式で指定してください');
  if (!(Number(cfg.width) >= 200 && Number(cfg.height) >= 150)) out.push('ウィンドウサイズが小さすぎます(幅200以上・高さ150以上)');
  return out;
};

const icon = (size) => {
  const px = new Uint8Array(size * size * 4), c = size / 2;
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const o = (y * size + x) * 4, d = Math.hypot(x - c + 0.5, y - c + 0.5) / c;
    if (d > 1) continue;
    px.set(d > 0.55 ? [79, 70, 229, 255] : [255, 255, 255, 255], o);
  }
  return encodePng(size, size, px);
};

function desktopProject(cfg, project, web) {
  const crate = slug(cfg.appName).replace(/-/g, '_') || 'app';
  const files = {};
  for (const [name, content] of Object.entries(web)) if (name !== 'README.md') files['src/' + name] = content;
  files['package.json'] = JSON.stringify({
    name: slug(cfg.appName) || 'app', version: cfg.version, private: true,
    scripts: { dev: 'tauri dev', build: 'tauri build', icon: 'tauri icon app-icon.png' },
    devDependencies: { '@tauri-apps/cli': '^1.5.0' },
  }, null, 2) + '\n';
  files['src-tauri/Cargo.toml'] = `[package]
name = "${crate}"
version = ${JSON.stringify(cfg.version)}
description = ${JSON.stringify(cfg.appName)}
edition = "2021"

[build-dependencies]
tauri-build = { version = "1", features = [] }

[dependencies]
tauri = { version = "1", features = ["clipboard-all", "dialog-open", "dialog-save", "fs-read-file", "fs-write-file", "notification-all", "window-set-fullscreen", "window-set-title"] }

[features]
# this feature is used for production builds or when \`devPath\` points to the filesystem
default = ["custom-protocol"]
custom-protocol = ["tauri/custom-protocol"]
`;
  files['src-tauri/build.rs'] = 'fn main() {\n    tauri_build::build()\n}\n';
  files['src-tauri/src/main.rs'] = `// Prevents an extra console window on Windows in release builds.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    tauri::Builder::default()
        .run(tauri::generate_context!())
        .expect("error while running the application");
}
`;
  files['src-tauri/tauri.conf.json'] = JSON.stringify({
    build: { distDir: '../src', devPath: '../src', withGlobalTauri: true },
    package: { productName: cfg.appName, version: cfg.version },
    tauri: {
      allowlist: {
        all: false,
        dialog: { open: true, save: true },
        fs: { readFile: true, writeFile: true, scope: ['$HOME/**', '$DOCUMENT/**', '$DESKTOP/**', '$DOWNLOAD/**'] },
        clipboard: { all: true },
        notification: { all: true },
        window: { setTitle: true, setFullscreen: true },
      },
      bundle: { active: true, targets: 'all', identifier: cfg.identifier, icon: ['icons/32x32.png', 'icons/128x128.png', 'icons/128x128@2x.png', 'icons/icon.icns', 'icons/icon.ico'] },
      security: { csp: null },
      windows: [{ title: cfg.appName, width: Number(cfg.width) || 1000, height: Number(cfg.height) || 700, resizable: true }],
    },
  }, null, 2) + '\n';
  files['src-tauri/icons/32x32.png'] = icon(32);
  files['src-tauri/icons/128x128.png'] = icon(128);
  files['src-tauri/icons/128x128@2x.png'] = icon(256);
  files['app-icon.png'] = icon(512);
  files['.gitignore'] = 'node_modules\n/src-tauri/target\n';
  files['README.md'] = `# ${cfg.appName}

A desktop app generated by [Codiram](https://github.com/Yumenyan/Codiram) (Desktop generator): your web app in \`src/\`
wrapped by [Tauri 1.x](https://tauri.app). It is an ordinary Tauri project — Codiram is not needed to build or edit it.

## Requirements

Node.js, Rust (https://rustup.rs) and the Tauri prerequisites for your OS (https://tauri.app/v1/guides/getting-started/prerequisites).

## Build

\`\`\`sh
npm install
npm run icon      # creates icons/icon.ico and icon.icns from app-icon.png (replace app-icon.png with your own icon)
npm run dev       # run the app
npm run build     # installer / bundle in src-tauri/target/release/bundle
\`\`\`

## Files

| File | |
|---|---|
| \`src/\` | The web app (index.html / style.css / app.js / data) — edit freely |
| \`src-tauri/tauri.conf.json\` | Window, permissions (allowlist) and bundle settings |
| \`src-tauri/src/main.rs\` | Tauri entry point |
| \`codiram.project.json\` | The Codiram project — import it in Codiram to keep editing visually |

Desktop blocks (file dialogs, clipboard, notifications, window control) call \`Desktop.*\` in \`src/app.js\`; it uses Tauri
inside the app and falls back to browser features when opened in a normal browser.
`;
  files['codiram.project.json'] = JSON.stringify(project, null, 2) + '\n';
  return files;
}

function generate(project, cfg) {
  cfg = cfg || targetConfig(project, 'desktop') || defaultDesktopConfig(project.name, project.name);
  const problems = validateDesktopConfig(cfg).map((msg) => ({ msg, config: true }));
  const files = desktopProject(cfg, project, generateWeb(project));
  return { files, problems, root: slug(cfg.appName) || 'app', entry: 'src/index.html' };
}

defineGenerator({
  id: 'desktop', order: 1, engine: 'blocks', inherits: 'web',
  name: J('デスクトップアプリ (Tauri)', 'Desktop app (Tauri)'),
  icon: '🖥',
  desc: J('Web アプリを Tauri プロジェクトとして包みます(ファイル・クリップボード・通知など)', 'Wraps the web app in a Tauri project (files, clipboard, notifications …)'),
  version: '0.1.0', language: ['html', 'css', 'javascript', 'rust'], platforms: ['windows', 'macos', 'linux'],
  supports: ['ui', 'events', 'variables', 'conditions', 'loops', 'functions', 'data', 'canvas', 'audio', 'game', 'animation', 'http', 'websocket', 'filesystem', 'clipboard', 'notification', 'window', 'dialog'],
  views: ['design', 'data', 'logic', 'preview'],
  defaultConfig: defaultDesktopConfig,
  validateConfig: validateDesktopConfig,
  configFields: [
    { key: 'appName', label: J('アプリ名', 'App name') },
    { key: 'identifier', label: J('識別子 (com.example.myapp)', 'Identifier (com.example.myapp)'), ph: 'com.example.myapp' },
    { key: 'version', label: J('バージョン', 'Version') },
    { key: 'width', label: J('ウィンドウ幅', 'Window width') },
    { key: 'height', label: J('ウィンドウ高さ', 'Window height') },
  ],
  generate,
});
